                string type=ItemBalance.Items[recipe].Id;if(!s.Workshop.learned[recipe]){game.Act(v=>Workshop.Learn(v,type),"blueprint-learn");UpdateView(true);return;}
                var q=Workshop.BatchQuote(s,type,quantity);if(!q.Allowed)return;var components=q.Components.Select((amount,index)=>new{amount,index}).Where(c=>c.amount>0).Select(c=>c.index).ToArray();
