        public void OpenBonuses(){var s=game.State;var roles=ItemBalance.Items.Select(d=>d.Role).Where(r=>r!="").Distinct().ToArray();var lines=new System.Collections.Generic.List<string>();foreach(var effect in ItemBalance.Items.SelectMany(d=>d.Profiles.SelectMany(p=>p)).Distinct()){double value=roles.Contains(effect)?Workshop.Device(s,effect):Workshop.Bonus(s,effect);if(value>1e-9)lines.Add(ItemDetailsUI.EffectName(s,effect)+": +"+(value*100).ToString("F2",System.Globalization.CultureInfo.GetCultureInfo(game.State.Settings.language))+" %");}OpenDetail(null,(s.Settings.language=="de"?"Aktive Ausrüstungsboni":"Active equipment bonuses")+"\n\n"+(lines.Count==0?(s.Settings.language=="de"?"Keine aktiven Ausrüstungsboni.":"No active equipment bonuses."):string.Join("\n",lines)));DetailPortrait.gameObject.SetActive(false);}
