            var synthesize=WorkshopUIFactory.Button("Synthesis"+index,DetailActions,UiLocalizedText.Translate("Herstellen",s.Settings.language),()=>{game.Act(v=>Industry.Synthesize(v,index));UpdateView(true);OpenComponent(index);});synthesize.interactable=game.Writable&&reason==null;
