        void OpenSlot(int n){OpenDetail(null,ItemPortrait.SlotName(ItemBalance.Slots[n],game.State.Settings.language)+"\n"+(n<3?"Grundslot":n<6?"Freischaltung im INT-Netz: "+new[]{"Zusatzprozessor","Zusatz-Core","Zusatz-Forschungssockel"}[n-3]+". Dauerhaft, auch nach Axiom.":"Modulares Modell"+(n==7?" "+UiLocalizedText.Translate("ab Level",game.State.Settings.language)+" "+ItemBalance.ModelSlotLevel:"")+". Modellentwicklung im Geheimen Labor unter Forschung."));DetailPortrait.Bind(null,ItemBalance.Slots[n].Replace("Aux",""));}
        public void OpenItem(string id,string requestedSlot=null)
        {
            var item=Item(id);if(item==null)return;var source=Rows.GetComponentsInChildren<ItemPortrait>().FirstOrDefault(p=>p.Item?.id==id);detailOrigin=source!=null?(Vector3?)source.Frame.transform.position:null;game.Audio?.Unlock();game.Audio?.Play("ui-click");var d=Workshop.Definition(item);string full=ItemDetailsUI.Text(game.State,item,requestedSlot);OpenDetail(item,full);var compare=full.IndexOf("\n\n<b>",StringComparison.Ordinal);DetailText.text=ItemDetailsUI.Primary(game.State,item)+(compare>=0?full.Substring(compare):"");
            string chosen=Workshop.EquipmentSlot(game.State,id,requestedSlot);if(chosen!=null){var equip=WorkshopUIFactory.Button("equip-"+chosen,DetailActions,UiLocalizedText.Translate("Ausrüsten",game.State.Settings.language),()=>{Vector3 origin=DetailPortrait.Frame.transform.position;string effect=ItemDetailsUI.Primary(game.State,item);var priorIncome=Game.Income(game.State);var priorData=Game.DataRate(game.State);bool committed=game.Act(s=>Workshop.Equip(s,id,chosen),"equip");CloseDetail();UpdateView(true);if(committed){var target=Equipment.GetComponentsInChildren<ItemPortrait>().FirstOrDefault(p=>p.name=="equipment-"+chosen);var flight=GetComponent<EquipFlight>()??gameObject.AddComponent<EquipFlight>();flight.Play(PortraitPrefab,item,origin,target,effect,game.State.Workshop.reducedMotion||!game.State.Settings.effects,Game.Income(game.State).CompareTo(priorIncome)!=0,Game.DataRate(game.State).CompareTo(priorData)!=0);}});GameTheme.CompactAction(equip,true);}

            if(game.State.Workshop.equipped.Contains(id)){string slot=ItemBalance.Slots[Array.IndexOf(game.State.Workshop.equipped,id)];WorkshopUIFactory.Button("Unequip",DetailActions,"Ablegen",()=>{game.Act(s=>Workshop.Unequip(s,slot),"unequip");CloseDetail();UpdateView(true);});}
            var more=WorkshopUIFactory.Vertical("MoreItemActions",DetailActions);var all=WorkshopUIFactory.Label("AllItemEffects",more.transform,string.Join("\n",full.Split('\n').Skip(2)),13);all.GetComponent<LayoutElement>().preferredHeight=all.preferredHeight+22;more.SetActive(false);var fold=WorkshopUIFactory.Button("MoreItemActionsToggle",DetailActions,"Weitere Aktionen",()=>{more.SetActive(!more.activeSelf);});fold.transform.SetSiblingIndex(DetailActions.childCount-2);
            WorkshopUIFactory.Button("Lock",more.transform,item.locked?"Entsperren":"Sperren",()=>{game.Act(s=>Workshop.Lock(s,id));OpenItem(id);UpdateView(true);});var q=Workshop.UpgradeQuote(game.State,item);var costRow=WorkshopUIFactory.Node("UpgradeCosts",DetailActions,typeof(CostStrip));costRow.GetComponent<CostStrip>().Bind(game,q);var upgrade=WorkshopUIFactory.Button("Upgrade",DetailActions,"Level erhöhen",()=>{game.Act(s=>Workshop.Upgrade(s,id,q.Revision),"upgrade");OpenItem(id);UpdateView(true);});upgrade.interactable=game.Writable&&q.Allowed;
            fold.GetComponent<Image>().color=Color.clear;GameTheme.CompactAction(upgrade,game.State.Workshop.equipped.Contains(id));upgrade.GetComponent<Image>().sprite=GameTheme.Steel;upgrade.GetComponent<Image>().color=Color.white;upgrade.GetComponentInChildren<Text>().color=upgrade.interactable?GameTheme.Text:GameTheme.Hex("6F7F99");fold.transform.SetAsLastSibling();more.transform.SetAsLastSibling();
            foreach(var slot in ItemBalance.Slots.Where(slot=>slot!=chosen&&Workshop.EquipmentSlot(game.State,id,slot)!=null)){string target=slot;WorkshopUIFactory.Button("choose-slot-"+slot,more.transform,ItemPortrait.SlotName(slot,game.State.Settings.language),()=>OpenItem(id,target));}
            foreach(var button in DetailActions.GetComponentsInChildren<Button>(true)){var height=button.GetComponent<LayoutElement>();if(height!=null)height.minHeight=height.preferredHeight=54;}
            DetailPortrait.Caption.text="";
            IndustryUI.Item(more.transform,game,id,()=>{OpenItem(id);UpdateView(true);});
            var salvage=WorkshopUIFactory.Button("SalvageItem",more.transform,"Zerlegen · nur gebundene Materialien zurückgewinnen",()=>{float roll=UnityEngine.Random.value;game.Act(v=>MetaAutomation.Salvage(v,id,Math.Min(.999999999,roll)),"salvage");CloseDetail();UpdateView(true);});salvage.interactable=game.Writable&&!Industry.Busy(game.State,id)&&!item.locked&&!item.challengeCopy&&!game.State.Workshop.equipped.Contains(id);
            WorkshopUIFactory.Button("SelectForFusion",more.transform,"Für Fusion auswählen",()=>{CloseDetail();ToggleSelection(id);});foreach(var button in more.GetComponentsInChildren<Button>(true)){var height=button.GetComponent<LayoutElement>();if(height!=null)height.minHeight=height.preferredHeight=54;}
        }
        void OpenRecipe(int index)
        {
            var d=ItemBalance.Items[index];var item=new ItemInstance{type=d.Id,level=1};OpenDetail(item,d.Name+"\n"+Costs(Workshop.Quote(game.State,d.Id))+"\nBauplanpreis: "+d.BlueprintPrice+" Fragmente. Wiederholte Herstellung kostet keine neuen Fragmente.");var learn=WorkshopUIFactory.Button("LearnBlueprint",DetailActions,game.State.Workshop.learned[index]?"Herstellen":"Bauplan lernen · "+d.BlueprintPrice+" Fragmente",()=>{if(game.State.Workshop.learned[index]){CloseDetail();SelectRecipe(index);}else if(game.Act(v=>Workshop.Learn(v,d.Id),"blueprint-learn")){OpenRecipe(index);UpdateView(true);}});GameTheme.ButtonStyle(learn,true);learn.interactable=game.Writable&&(game.State.Workshop.learned[index]||Workshop.LearnBlock(game.State,index)==null);int level=game.State.Workshop.mastery[index];var b=WorkshopUIFactory.Button("Mastery",DetailActions,"Meisterschaft "+level+" → "+Math.Min(4,level+1),()=>{game.Act(s=>Workshop.Mastery(s,d.Id,level));OpenRecipe(index);UpdateView(true);});b.interactable=level<4&&game.State.Workshop.crafted[index]>0&&game.State.Workshop.fragments>=ItemBalance.MasteryCosts[Math.Min(3,level)]&&game.State.Workshop.learned[index];
        }
        void OpenDetail(ItemInstance item,string text){DetailRoot.SetActive(true);WorkshopUIFactory.Clear(DetailActions);DetailPortrait.gameObject.SetActive(true);DetailPortrait.Bind(item);var lines=text.Split('\n');DetailName.text=lines[0].Replace("<b>","").Replace("</b>","");DetailMeta.text=item==null?"":SettingsRules.Text(game.State.Settings.language,"rarity:"+ItemBalance.Rarities[item.rarity]).ToUpperInvariant()+" · Lv. "+item.level;DetailMeta.color=item==null?GameTheme.Muted:ItemPortrait.RarityColor(item.rarity);DetailText.text=string.Join("\n",lines.Skip(item==null||string.IsNullOrEmpty(item.id)?1:2));PanelMotion.Play(DetailRoot.transform.Find("DetailPanel").gameObject,game.State.Workshop.reducedMotion||!game.State.Settings.effects,false,detailOrigin);detailOrigin=null;PanelMotion.Play(DetailPortrait.gameObject,item==null||game.State.Workshop.reducedMotion||!game.State.Settings.effects,true);var scroll=DetailRoot.GetComponentInChildren<ScrollRect>(true);Canvas.ForceUpdateCanvases();scroll.verticalNormalizedPosition=1;}
        public void CloseDetail(){DetailRoot.SetActive(false);}
